## t001: fix: handle web stream payload in HEAD route

Fixes #6371

Issue #6371: HEAD route throws `ERR_INVALID_ARG_TYPE` error when GET route sends a Web Stream

### Prerequisites

- [x] I have written a descriptive issue title
- [x] I have searched existing issues to ensure the bug has not already been reported

### Fastify version

5.6.1

### Plugin version

_No response_

### Node.js version

22.18.0

### Operating system

macOS

### Operating system version (i.e. 20.04, 11.3, 10)

15.6

### Description

### Summary
Fastify automatically creates a corresponding `HEAD` route for every `GET` route. However, if the `GET` route handler sends a Web Stream (e.g., a `ReadableStream`), making a request to the `HEAD` route throws a `TypeError`.

### Steps to Reproduce
1. Register a `GET` route that replies with a Web Stream payload (e.g., `new ReadableStream(...)`).
2. Start the Fastify server.
3. Send a `HEAD` request to the same route.
4. The server crashes with the error below.

### Error Details
The following `TypeError` is thrown:

```
TypeError [ERR_INVALID_ARG_TYPE]: The "string" argument must be of type string or an instance of Buffer or ArrayBuffer. Received an instance of ReadableStream
    at Function.byteLength (node:buffer:777:11)
    ...
```

### Analysis
This error originates from the `headRouteOnSendHandler` function, specifically at this line:

This line incorrectly assumes the payload is a Buffer-like type (`string`, `Buffer`, or `ArrayBuffer`, ...) to calculate the `Content-Length`.
Thus `Buffer.byteLength` fails causing the error when the payload is a `ReadableStream`.

### Link to code that reproduces the bug

https://github.com/orionmiz/fastify-repro-web-stream-in-head

### Expected Behavior

**HEAD request to a route whose corresponding GET handler sends a Web Stream should not throw an error.**

- The `headRouteOnSendHandler` should not attempt to calculate the `Content-Length` of a stream payload (e.g., by calling `Buffer.byteLength`).
- Instead, in accordance with the HTTP specification, the `HEAD` response must include the exact same headers (such as `Transfer-Encoding` or `Content-Length`) that would have been sent by the corresponding `GET` request.

You may update existing tests whose expectations your change intentionally alters.

Acceptance tests:

`test/route.6.pr6372.test.js`

```js
'use strict'

const stream = require('node:stream')
const { ReadableStream } = require('node:stream/web')
const { test } = require('node:test')
const Fastify = require('..')

test('HEAD route should handle properly each response type', async t => {
  t.plan(24)

  const fastify = Fastify({ exposeHeadRoutes: true })
  const resString = 'Found me!'
  const resJSON = { here: 'is Johnny' }
  const resBuffer = Buffer.from('I am a buffer!')
  const resStream = stream.Readable.from('I am a stream!')
  const resWebStream = ReadableStream.from('I am a web stream!')

  fastify.route({
    method: 'GET',
    path: '/json',
    handler: (req, reply) => {
      reply.send(resJSON)
    }
  })

  fastify.route({
    method: 'GET',
    path: '/string',
    handler: (req, reply) => {
      reply.send(resString)
    }
  })

  fastify.route({
    method: 'GET',
    path: '/buffer',
    handler: (req, reply) => {
      reply.send(resBuffer)
    }
  })

  fastify.route({
    method: 'GET',
    path: '/buffer-with-content-type',
    handler: (req, reply) => {
      reply.headers({ 'content-type': 'image/jpeg' })
      reply.send(resBuffer)
    }
  })

  fastify.route({
    method: 'GET',
    path: '/stream',
    handler: (req, reply) => {
      return resStream
    }
  })

  fastify.route({
    method: 'GET',
    path: '/web-stream',
    handler: (req, reply) => {
      return resWebStream
    }
  })

  let res = await fastify.inject({
    method: 'HEAD',
    url: '/json'
  })
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(res.headers['content-type'], 'application/json; charset=utf-8')
  t.assert.strictEqual(res.headers['content-length'], `${Buffer.byteLength(JSON.stringify(resJSON))}`)
  t.assert.deepStrictEqual(res.body, '')

  res = await fastify.inject({
    method: 'HEAD',
    url: '/string'
  })
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(res.headers['content-type'], 'text/plain; charset=utf-8')
  t.assert.strictEqual(res.headers['content-length'], `${Buffer.byteLength(resString)}`)
  t.assert.strictEqual(res.body, '')

  res = await fastify.inject({
    method: 'HEAD',
    url: '/buffer'
  })
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(res.headers['content-type'], 'application/octet-stream')
  t.assert.strictEqual(res.headers['content-length'], `${resBuffer.byteLength}`)
  t.assert.strictEqual(res.body, '')

  res = await fastify.inject({
    method: 'HEAD',
    url: '/buffer-with-content-type'
  })
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(res.headers['content-type'], 'image/jpeg')
  t.assert.strictEqual(res.headers['content-length'], `${resBuffer.byteLength}`)
  t.assert.strictEqual(res.body, '')

  res = await fastify.inject({
    method: 'HEAD',
    url: '/stream'
  })
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(res.headers['content-type'], undefined)
  t.assert.strictEqual(res.headers['content-length'], undefined)
  t.assert.strictEqual(res.body, '')

  res = await fastify.inject({
    method: 'HEAD',
    url: '/web-stream'
  })
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(res.headers['content-type'], undefined)
  t.assert.strictEqual(res.headers['content-length'], undefined)
  t.assert.strictEqual(res.body, '')
})
```

`test/route.7.pr6372.test.js`

```js
'use strict'

const stream = require('node:stream')
const { ReadableStream } = require('node:stream/web')
const split = require('split2')
const { test } = require('node:test')
const Fastify = require('..')
const createError = require('@fastify/error')

test('HEAD route should handle ReadableStream.cancel() error', (t, done) => {
  t.plan(7)

  const logStream = split(JSON.parse)
  const expectedError = new Error('Cancel error!')
  const fastify = Fastify({
    logger: {
      stream: logStream,
      level: 'error'
    }
  })

  fastify.route({
    method: 'GET',
    path: '/web-stream',
    exposeHeadRoute: true,
    handler: (req, reply) => {
      const webStream = new ReadableStream({
        start (controller) {
          controller.enqueue('Hello from web stream!')
        },
        cancel (reason) {
          t.assert.strictEqual(reason, 'Stream cancelled by HEAD route')
          throw expectedError
        }
      })
      return webStream
    }
  })

  logStream.once('data', line => {
    const { message, stack } = expectedError
    t.assert.deepStrictEqual(line.err, { type: 'Error', message, stack })
    t.assert.strictEqual(line.msg, 'Error on Stream found for HEAD route')
    t.assert.strictEqual(line.level, 50)
  })

  fastify.inject({
    method: 'HEAD',
    url: '/web-stream'
  }, (error, res) => {
    t.assert.ifError(error)
    t.assert.strictEqual(res.statusCode, 200)
    t.assert.strictEqual(res.headers['content-type'], undefined)
    done()
  })
})
```

## t002: fix: consistent error handling for custom validators in async validation contexts

## Description

Fixes inconsistent error handling between sync and async validation contexts when custom validators throw errors instead of returning `{error}` objects.

## Problem

When using async preValidation hooks with custom validators, if the validator throws an error (instead of returning `{error}`), the error would not be caught by the error handler and would result in an unhandled promise rejection, potentially crashing the application.

This inconsistency meant:
- **Sync context**: Thrown errors were caught and handled properly by the error handler
- **Async context**: Thrown errors became unhandled promise rejections

## Solution

Modified the `validateParam` function in `lib/validation.js` to wrap the `validatorFunction` call in a try-catch block. This ensures that synchronous throws are caught and returned as validation errors, making error handling consistent across both sync and async validation contexts.

## Changes

- **lib/validation.js**: Added try-catch block around `validatorFunction` call in `validateParam`
- **test/validation-error-handling.test.js**: Added test case to verify error handling consistency

## Testing

- ✅ All existing tests pass
- ✅ New test specifically validates the fix for async preValidation + custom validator error scenarios
- ✅ Covers the exact issue described in #6214

## Breaking Changes

None. This change maintains backward compatibility while fixing the error handling inconsistency.

Fixes #6214

You may update existing tests whose expectations your change intentionally alters.

Acceptance tests:

`test/validation-error-handling.pr6247.test.js`

```js
'use strict'

const { describe, test } = require('node:test')
const Joi = require('joi')
const Fastify = require('..')

const schema = {
  body: {
    type: 'object',
    properties: {
      name: { type: 'string' },
      work: { type: 'string' }
    },
    required: ['name', 'work']
  }
}

function echoBody (req, reply) {
  reply.code(200).send(req.body.name)
}

describe('sync and async must work in the same way', () => {
  // Route with custom validator that throws
  const throwingRouteValidator = {
    schema: {
      body: {
        type: 'object',
        properties: { name: { type: 'string' } }
      }
    },
    validatorCompiler: () => {
      return function (inputData) {
        // This custom validator throws a sync error instead of returning `{ error }`
        throw new Error('Custom validation failed')
      }
    },
    handler (request, reply) { reply.send({ success: true }) }
  }

  test('async preValidation with custom validator should trigger error handler when validator throws', async (t) => {
    t.plan(4)

    const fastify = Fastify()
    fastify.setErrorHandler((error, request, reply) => {
      t.assert.ok(error instanceof Error, 'error should be an Error instance')
      t.assert.strictEqual(error.message, 'Custom validation failed')
      reply.status(500).send({ error: error.message })
    })

    // Add async preValidation hook
    fastify.addHook('preValidation', async (request, reply) => {
      await Promise.resolve('ok')
    })
    fastify.post('/async', throwingRouteValidator)

    const response = await fastify.inject({
      method: 'POST',
      url: '/async',
      payload: { name: 'test' }
    })
    t.assert.strictEqual(response.statusCode, 500)
    t.assert.deepStrictEqual(response.json(), { error: 'Custom validation failed' })
  })

  test('sync preValidation with custom validator should trigger error handler when validator throws', async (t) => {
    t.plan(4)

    const fastify = Fastify()
    fastify.setErrorHandler((error, request, reply) => {
      t.assert.ok(error instanceof Error, 'error should be an Error instance')
      t.assert.strictEqual(error.message, 'Custom validation failed')
      reply.status(500).send({ error: error.message })
    })

    // Add sync preValidation hook
    fastify.addHook('preValidation', (request, reply, next) => { next() })
    fastify.post('/sync', throwingRouteValidator)

    const response = await fastify.inject({
      method: 'POST',
      url: '/sync',
      payload: { name: 'test' }
    })
    t.assert.strictEqual(response.statusCode, 500)
    t.assert.deepStrictEqual(response.json(), { error: 'Custom validation failed' })
  })
})
```

